import React from 'react';
import { Card, CardContent } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';

export default function ProjectsSection() {
  const projects = [
    {
      title: 'Techzo',
      description:
        'Techzo is a cutting-edge design agency template built to showcase innovation, digital expertise, and a bold creative presence online',
      tags: ['HTML5 & CSS', 'Framer Motion', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/1827805025.jpeg',
    },
    {
      title: 'Lumin Studio',
      description:
        'LuminStudio blends elegance and clarity — a modern design agency template crafted to highlight creative work and impress potential clients',
      tags: ['HTML5 & Tailwind CSS', 'React', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/429890704.jpeg',
    },
    {
      title: 'Nubuilt',
      description:
        'Crafted with clean, semantic code — Nubuilt is a sleek architecture template built for performance, responsiveness, and timeless design.',
      tags: ['HTML5', 'CSS', 'GSAP'],
      image: 'https://ext.same-assets.com/498039404/1730903789.jpeg',
    },
    {
      title: 'Design orbit',
      description:
        'Bold, creative, and conversion-focused — DesignOrbit is a sleek portfolio website template made for design agencies to showcase their work and attract clients.',
      tags: ['HTML5 & CSS', 'GSAP', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/3079166500.jpeg',
    },
  ];

  return (
    <section className="py-20 container mx-auto px-6 lg:px-16">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center gap-4 mb-12">
          <span className="text-sm text-gray-400">// Explore Work</span>
          <div className="flex-1 h-px bg-gray-600"></div>
        </div>
        <h2 className="text-4xl lg:text-5xl font-bold mb-16 text-white">A Showcase of My Latest Projects</h2>
        <div className="grid md:grid-cols-2 gap-8 mb-12">
          {projects.map((project, index) => (
            <Card key={index} className="overflow-hidden bg-gray-900/50 border-gray-600">
              <div className="aspect-video overflow-hidden">
                <img
                  src={project.image || '/placeholder.svg'}
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-300 hover:scale-105"
                />
              </div>
              <CardContent className="p-6">
                <h3 className="text-xl font-semibold mb-3 text-white">{project.title}</h3>
                <p className="text-gray-400 mb-4 text-sm leading-relaxed">{project.description}</p>
                <div className="flex flex-wrap gap-2">
                  {project.tags.map((tag) => (
                    <Badge key={tag} variant="secondary" className="text-xs bg-teal-500/20 text-teal-500">
                      {tag}
                    </Badge>
                  ))}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
        <div className="text-center">
          <Button className="rounded-full bg-teal-500 hover:bg-teal-600 text-white">View More Projects</Button>
        </div>
      </div>
    </section>
  );
}
